class Solution:
    def numberOfPairs(self, nums1: List[int], nums2: List[int], k: int) -> int:
        return sum(1 for a in nums1 for b in nums2 if a % (b * k) == 0)

c.cpp:
class Solution {
public:
    int numberOfPairs(vector<int>& nums1, vector<int>& nums2, int k) {
        int cnt = 0;
        for (int a : nums1)
            for (int b : nums2)
                if (a % ((long long)b * k) == 0) cnt++;
        return cnt;
    }
};

