class Solution:
    def numberOfPairs(self, nums1: List[int], nums2: List[int], k: int) -> int:
        from collections import Counter
        freq = Counter(nums1)
        ans = 0
        for b in nums2:
            m = b * k
            for v in range(m, 51, m):
                ans += freq[v]
        return ans

