class Solution {
public:
    int numberOfPairs(vector<int>& nums1, vector<int>& nums2, int k) {
        int freq[51] = {};
        for (int a : nums1) freq[a]++;
        int ans = 0;
        for (int b : nums2) {
            long long m = (long long)b * k;
            for (long long v = m; v <= 50; v += m) ans += freq[v];
        }
        return ans;
    }
};

